-- evt:gate
RegisterEvent(45, "True-name gate", function(continueStep)
    if continueStep == 2 then
        evt.SetDoorState(23, DoorAction.Open)
        evt.SetDoorState(24, DoorAction.Open)
        XeenQuests.hook("m33.true_name_gate")
        evt.PlaySoundName("xeen_power_up")
        return
    end
    if continueStep ~= nil then
        XeenQuests.hook("m33.true_name_wrong")
        return
    end
    if not ((not (IsQBitSet(QBit(111661)))) and ((Xeen.alamarSundialsSync()))) then
        if IsQBitSet(QBit(111661)) then evt.StatusText("The gate stands open.") else XeenQuests.hook("m33.true_name_gate") end
        return
    end
    evt.AskQuestion(45, 1, 0, 2, "The time is right. What is Alamar's true name?", {"Sheltem"})
end, "True-name gate")

