-- evt:vault_load
RegisterEvent(94, nil, function()
    if not (IsQBitSet(QBit(117605))) then
        return
    end
    evt.SetDoorState(34, DoorAction.Open)
end, nil)

-- evt:vault_release
RegisterEvent(95, "Vault release: the strongroom by Command Central", function(continueStep)
    local eventId = 95
    if not ((continueStep == 1)) then
        if continueStep ~= nil then
            return
        end
        if IsQBitSet(QBit(117605)) then
            evt.StatusText("The release is down. The strongroom stands open.")
            return
        end
        AskChoiceWithAnswerSteps(eventId, 3, "Vault release. Pull?", {{Answer = "Yes", Step = 1}, {Answer = "No", Step = 2}})
        evt.SetDoorState(42, DoorAction.Close)
        return
    end
    evt.SetDoorState(34, DoorAction.Open)
    evt.SetDoorState(42, DoorAction.Open)
    SetQBit(QBit(117605))
    evt.StatusText("Far off, a heavy door grinds up.", 4)
end, "Vault release: the strongroom by Command Central")

